def regioes():
    return {"sul": ["chapeco", "florianopolis"], "norte": ["manaus"]}


def adicionar_cidade(mapa, regiao, cidade):
    lista = mapa.setdefault(regiao, [])
    lista.append(cidade)
    return lista
